        <!-- Email -->
        <div class="input-group">
          <input
            type="email"
            v-model="email"
            @blur="emailTouched = true"
            required
          />

          <label
            :class="{
              active: email || emailTouched
            }"
          >
            Email
          </label>
        </div>

        <p
          v-if="emailTouched && !email"
          class="error"
        >
          Email is required.
        </p>

        <!-- Password -->

        <div class="input-group password">
          <input
            :type="showPassword ? 'text' : 'password'"
            placeholder="Password"
            v-model="password"
          />

          <span
            class="eye"
            @click="showPassword=!showPassword"
          >
            {{ showPassword ? '🙈' : '👁️' }}
          </span>
        </div>

        <button
          :disabled="!formValid"
        >
          Sign In
        </button>

      </form>

      <div class="links">
        <ul>
          <li>Can't access your account?</li>
          <li>Don't have an account? Register now.</li>
        </ul>
      </div>

    </div>

    <div class="version">
      Version: 26.13.2
    </div>

  </div>
