<script>
export default {
  data() {
    return {
      email: "",
      password: "",
      showPassword: false,
      emailTouched: false,
    };
  },

  computed: {
    formValid() {
      return (
        this.email.trim() !== "" &&
        this.password.trim() !== ""
      );
    },
  },

  methods: {
    login() {
      alert("Login");
    },
  },
};
